''','''        elif command == "prio":
            args = rest.split(" ")
            id_text = args[0]
            p = args[1] if len(args) > 1 else ""
            task = None
            if id_text.isascii() and id_text.isdigit():
                task = find(tasks, int(id_text))
            if task is None:
                print(f"no such task {id_text}")
            elif len(p) == 1 and p in "0123456789":
                task.prio = int(p)
                print(f"prio {task.id} {p}")
            else:
                print(f"bad priority {p}")
        elif command == "list":
            ordered = sorted(tasks, key=lambda t: (t.prio, t.id))
            if rest == "all":
                for task in ordered:
                    mark = "x" if task.done else "-"
                    print(f"{mark} {task.id} {task.title}")
            else:
                for task in ordered:
                    if not task.done:
                        print(f"{task.id} {task.title}")
        else:
            print(f"? {command}")
''')
